      {/* SECTION 3: ALTERNATIVE LSTM ANALYTICS & CONVERGENCE */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '20px' }}>
