        <div className="card" style={{ background: '#ffffff', borderRadius: '16px', padding: '20px', border: '1px solid #dbe6ef' }}>
          <h3 style={{ margin: '0 0 4px 0', fontSize: '1.15rem', color: '#1a3c54' }}>
            📊 Alternative LSTM Pipeline Analytics
